        if not isinstance(term, str):
            raise TypeError("every term must be a string")
        if not term or any(ch < "a" or ch > "z" for ch in term):
            raise ValueError("terms must be non-empty lowercase ASCII strings")
        unique_terms.add(term)
    ordered_terms = sorted(unique_terms)

    @lru_cache(maxsize=None)
    def visit(position):
        if position == len(text):
            return ()
        results = []
        for term in ordered_terms:
            if text.startswith(term, position):
                for suffix in visit(position + len(term)):
                    results.append((term,) + suffix)
        return tuple(results)

    return sorted(set(visit(0)))

