import unittest
from solution import split_compound


class SplitCompoundTests(unittest.TestCase):
    def test_all_splits_sorted_without_duplicates(self):
        terms = ['a', 'aa', 'a', 'aaa']
        self.assertEqual(
            split_compound('aaa', terms),
            [('a', 'a', 'a'), ('a', 'aa'), ('aa', 'a'), ('aaa',)],
        )

    def test_terms_can_be_reused(self):
        self.assertEqual(split_compound('catcat', ['cat']), [('cat', 'cat')])

    def test_empty_and_unsplittable_text(self):
        self.assertEqual(split_compound('', []), [()])
        self.assertEqual(split_compound('abc', ['a', 'bcx']), [])

    def test_one_shot_terms_iterable(self):
        terms = (term for term in ['bed', 'bath', 'bedbath'])
        self.assertEqual(split_compound('bedbath', terms), [('bed', 'bath'), ('bedbath',)])

    def test_supplied_container_is_not_mutated_or_aliased(self):
        terms = ['a', 'aa']
        result = split_compound('aa', terms)
        self.assertEqual(terms, ['a', 'aa'])
        result.append(('changed',))
        self.assertEqual(split_compound('aa', terms), [('a', 'a'), ('aa',)])

    def test_invalid_outer_types(self):
        for text in (None, 1, b'abc'):
            with self.subTest(text=text):
                with self.assertRaises(TypeError):
                    split_compound(text, [])
        for terms in (None, 3):
            with self.subTest(terms=terms):
                with self.assertRaises(TypeError):
                    split_compound('abc', terms)

    def test_invalid_strings_and_term_types(self):
        for text in ('ABC', 'a1', 'a b', 'é'):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    split_compound(text, ['a'])
        for terms, error in (([''], ValueError), (['A'], ValueError), (['a-b'], ValueError), (['é'], ValueError), (['a', 2], TypeError)):
            with self.subTest(terms=terms):
                with self.assertRaises(error):
                    split_compound('a', terms)


if __name__ == '__main__':
    unittest.main()

